using System;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
public sealed class ManualHypothesisEditor:UserControl {
 readonly string root;readonly Dictionary<string,object>source;readonly Action<string>finish;readonly RichTextBox original=new RichTextBox{Name="ManualSource",Dock=DockStyle.Top,Height=170,ReadOnly=true,DetectUrls=false};readonly Label quote=new Label{Name="ManualQuote",AutoSize=true,MaximumSize=new Size(700,0)};readonly Label message=new Label{Name="ManualMessage",AutoSize=true,ForeColor=Color.DarkRed,MaximumSize=new Size(700,0)};readonly Dictionary<string,TextBox>fields=new Dictionary<string,TextBox>();readonly ManualHypotheses.Record previous;Form watched;bool dirty,saved,initialized;readonly string recoveryId;string recoveryExpected="";int start=-1,end=-1;
 public ManualHypothesisEditor(string root,Dictionary<string,object>source,Action<string>finish,ManualHypotheses.Record previous=null,ManualDraftRecovery.Draft recovery=null){recoveryId=recovery==null?Guid.NewGuid().ToString("N"):recovery.Id;recoveryExpected=recovery==null?"":recovery.Hash;this.previous=previous;this.root=root;this.source=source;this.finish=finish;Dock=DockStyle.Fill;AutoScroll=true;var layout=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,Padding=new Padding(8)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(layout);layout.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(700,0),Text="Ручная гипотеза: непроверенный черновик. Выделите точную цитату в тексте ниже. Пакет, ответ или заголовок не доказывает спрос. Сохранение не добавляет бизнес-кандидата и не одобряет генерацию."});layout.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(700,0),Text=ManualHypotheses.S(source,"url")+"\r\nРоль: "+ManualHypotheses.S(source,"kind")+" | автор: "+ManualHypotheses.S(source,"author")+"\r\nОбласть: "+ManualHypotheses.S(source,"text_scope")});original.Text=ManualHypotheses.S(source,"text");layout.Controls.Add(original);var bind=new Button{Text="Использовать выделенную цитату",Name="BindManualQuote",AutoSize=true};bind.Click+=(s,e)=>BindSelection();layout.Controls.Add(bind);quote.Text="Цитата пока не выбрана.";layout.Controls.Add(quote);
 foreach(var pair in new[]{new[]{"title","Название гипотезы", ""},new[]{"interpretation","Моя интерпретация / гипотеза — не факт", ""},new[]{"assumptions","Допущения и неизвестное", ""},new[]{"buyer_role","Предполагаемая роль покупателя — необязательно, не клиент", "не установлена"},new[]{"next_action","Следующий проверяемый шаг — ещё не выполнен", ""},new[]{"success","Какой результат поддержит гипотезу", ""},new[]{"failure","Какой результат опровергнет её или оставит неизвестной", ""}}){layout.Controls.Add(new Label{AutoSize=true,Text=pair[1]});var box=new TextBox{Name="Manual_"+pair[0],Dock=DockStyle.Top,Multiline=pair[0]!="title",Height=pair[0]=="title"?26:65,MaxLength=pair[0]=="title"?200:4000,Text=previous==null?pair[2]:ManualHypotheses.S(previous.Data,pair[0])};fields.Add(pair[0],box);box.TextChanged+=(s,e)=>{dirty=true;PersistRecovery();};layout.Controls.Add(box);}var buttons=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top};var save=new Button{Name="SaveManualHypothesis",Text="Сохранить непроверенный черновик",AutoSize=true};save.Click+=(s,e)=>{string id;if(TrySave(out id))finish(id);};var cancel=new Button{Name="CancelManualHypothesis",Text="Отмена",AutoSize=true};cancel.Click+=(s,e)=>{if(!dirty||MessageBox.Show(FindForm(),"Отменить несохранённый черновик?","RevEng",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){if(!DiscardRecovery())return;dirty=false;finish(null);}};buttons.Controls.Add(save);buttons.Controls.Add(cancel);layout.Controls.Add(buttons);layout.Controls.Add(message);if(previous!=null){var r=ManualHypotheses.D(ManualHypotheses.V(previous.Data,"reference"));start=Convert.ToInt32(r["start"]);end=Convert.ToInt32(r["end"]);quote.Text="Цитата прежней ревизии ["+start+","+end+"):\r\n"+ManualHypotheses.S(r,"quote");message.Text="Редактируется новая ревизия. Прежняя запись останется неизменной.";}if(recovery!=null){var data=recovery.Data;var values=ManualHypotheses.D(ManualHypotheses.V(data,"fields"));foreach(var key in fields.Keys)fields[key].Text=ManualHypotheses.S(values,key);start=Convert.ToInt32(data["start"]);end=Convert.ToInt32(data["end"]);dirty=true;quote.Text=start<0?"Цитата ещё не выбрана.":"Восстановленная цитата: "+ProvenanceAudit.Slice(ManualHypotheses.S(source,"text"),start,end);message.Text="Восстановлен незавершённый текст. Это ещё не сохранённая гипотеза. Перед фиксацией источник проверяется заново.";}initialized=true;}
 protected override void OnParentChanged(EventArgs e){base.OnParentChanged(e);if(watched!=null)watched.FormClosing-=Closing;watched=FindForm();if(watched!=null)watched.FormClosing+=Closing;}
 void Closing(object sender,FormClosingEventArgs e){if(!dirty||saved)return;var answer=MessageBox.Show(watched,"Есть несохранённая ручная гипотеза. Сохранить черновик перед закрытием?","RevEng",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)e.Cancel=true;else if(answer==DialogResult.Yes){string id;if(!TrySave(out id))e.Cancel=true;}else{if(!DiscardRecovery())e.Cancel=true;else dirty=false;}}
 protected override void Dispose(bool disposing){if(disposing&&watched!=null){watched.FormClosing-=Closing;watched=null;}base.Dispose(disposing);}
 bool DiscardRecovery(){try{if(recoveryExpected!=""){ManualDraftRecovery.Remove(root,recoveryId,recoveryExpected);recoveryExpected="";}return true;}catch(Exception ex){message.Text="Незавершённая копия сохранена: "+ex.Message;return false;}}
 void PersistRecovery(){if(!initialized||!dirty||saved)return;try{var data=new Dictionary<string,object>{{"schema","reveng-editor-recovery-v1"},{"status","INCOMPLETE_EDITOR_WORK_NOT_HYPOTHESIS"},{"auto_admission",false},{"saved_at",DateTimeOffset.UtcNow.ToString("o")},{"source_snapshot",source},{"previous_id",previous==null?"":previous.Id},{"start",start},{"end",end},{"fields",fields.ToDictionary(p=>p.Key,p=>(object)p.Value.Text)}};recoveryExpected=ManualDraftRecovery.Save(root,recoveryId,data,recoveryExpected);message.Text="Незавершённый текст сохранён для восстановления при переходе. Это не зафиксированная гипотеза.";}catch(Exception ex){message.Text="Не удалось сохранить незавершённый текст: "+ex.Message+". Не уходите из редактора; скопируйте текст.";}}
 // RichTextBox normalizes CRLF for display. Map its UTF16 selection back to the unchanged original text, then count Unicode codepoints.
 public static int[] MapSelection(string raw,string displayed,int selectionStart,int selectionLength){if(selectionStart<0||selectionLength<=0||selectionStart+selectionLength>displayed.Length)throw new ArgumentException("Выделите текст источника.");var normalized=new StringBuilder();var map=new List<int>{0};for(int i=0;i<raw.Length;i++){if(raw[i]=='\r'){normalized.Append('\n');if(i+1<raw.Length&&raw[i+1]=='\n')i++;}else normalized.Append(raw[i]);map.Add(i+1);}if(normalized.ToString()!=displayed)throw new ArgumentException("Отображаемый текст отличается от сохранённого. Цитата не сохранена.");int a=map[selectionStart],b=map[selectionStart+selectionLength];if(a>0&&a<raw.Length&&char.IsLowSurrogate(raw[a])&&char.IsHighSurrogate(raw[a-1])||b>0&&b<raw.Length&&char.IsLowSurrogate(raw[b])&&char.IsHighSurrogate(raw[b-1]))throw new ArgumentException("Выделите символ Unicode целиком.");return new[]{ProvenanceAudit.Count(raw.Substring(0,a)),ProvenanceAudit.Count(raw.Substring(0,b))};}
 void BindSelection(){try{var range=MapSelection(ManualHypotheses.S(source,"text"),original.Text,original.SelectionStart,original.SelectionLength);if(range[1]-range[0]>1000)throw new ArgumentException("Выберите до1000 символов Unicode.");start=range[0];end=range[1];quote.Text="Точная цитата ["+start+","+end+"):\r\n"+ProvenanceAudit.Slice(ManualHypotheses.S(source,"text"),start,end);dirty=true;message.Text="";PersistRecovery();}catch(Exception ex){message.Text=ex.Message;}}
 bool TrySave(out string id){id=null;try{if(previous!=null&&!dirty)throw new ArgumentException("Нет новых правок; прежняя ревизия сохранена.");if(start<0)throw new ArgumentException("Сначала выберите точную цитату.");var note=ManualHypotheses.Create(EvidenceBindings.Capture(root,source),start,end,fields.ToDictionary(p=>p.Key,p=>p.Value.Text));if(previous!=null)note["supersedes"]=previous.Id;id=ManualHypotheses.Save(root,note);dirty=false;saved=true;try{DiscardRecovery();}catch(Exception ex){message.Text="Гипотеза сохранена, но незавершённая копия осталась: "+ex.Message;}return true;}catch(Exception ex){message.Text="Черновик не сохранён: "+ex.Message+". Исходные материалы и прежние заметки не изменены.";return false;}}
}
